#include <list>
#include <algorithm>
#include <iostream>

struct Item { int key; int id; };

int main() {
    std::list<Item> l = {{5, 1}, {3, 2}, {5, 3}, {1, 4}};

    // Stable sort based on key
    l.sort([](const Item& a, const Item& b) {
        return a.key < b.key;
    });

    // Result: (1, 4), (3, 2), (5, 1), (5, 3) 
    // (5, 1) remains before (5, 3) due to stability.
}
